extends "res://tests/experimental/adaptive_offline.gd"

# Experimental second-order coarse operator for the *reference map*, not an
# ODE reimplementation. Every slope is measured using Simulation.update(0.1).
# The outer step-doubling controller and all discrete guards remain authoritative.
var map_operator_usec: int = 0


func _init(game_simulation: Simulation) -> void:
	super(game_simulation)
	numerical_retry_max_ticks = 1000


func run(seconds: float) -> Dictionary:
	map_operator_usec = 0
	var result: Dictionary = super(seconds)
	counters["map_operator_usec"] = map_operator_usec
	result["map_operator_usec"] = map_operator_usec
	return result


func _advance(delta: float, end: float) -> void:
	if delta <= REFERENCE_STEP + 1e-12:
		super(delta, end)
		return
	var started: int = Time.get_ticks_usec()
	_map_advance(delta, end)
	map_operator_usec += Time.get_ticks_usec() - started


func _map_advance(delta: float, end: float) -> void:
	var saved: Dictionary = Checkpoint.capture(simulation)
	var initial: Dictionary = Metrics.numeric(simulation.state)
	super._advance(REFERENCE_STEP, end - delta + REFERENCE_STEP)
	var first: Dictionary = Metrics.numeric(simulation.state)
	var ticks: float = delta / REFERENCE_STEP
	var predicted: Dictionary = {}
	for id in simulation.state.resources:
		var key: String = "resource/" + str(id)
		predicted[id] = float(initial[key]) + ticks * (float(first[key]) - float(initial[key]))
		if not is_finite(predicted[id]) or float(predicted[id]) < 0.0:
			trial_failure_reason = "predictor_resource_exhaustion"
			Checkpoint.restore(simulation, saved)
			return
	Checkpoint.restore(simulation, saved)
	for id in predicted:
		simulation.state.resources[id].amount = predicted[id]
	var before_probe: Dictionary = Metrics.numeric(simulation.state)
	super._advance(REFERENCE_STEP, end)
	var endpoint: Dictionary = Metrics.numeric(simulation.state)
	var result: Dictionary = {}
	for key in first:
		var base: float = float(initial.get(key, 0.0))
		var d0: float = float(first[key]) - base
		var d1: float = float(endpoint.get(key, 0.0)) - float(before_probe.get(key, 0.0))
		# For n=1 this is F_0.1 exactly. For n>1, the (n-1) correction
		# matches the n(n-1)/2 term of repeated discrete-map composition.
		result[key] = base + ticks * d0 + (ticks - 1.0) * 0.5 * (d1 - d0)
	for key in result:
		var value: float = float(result[key])
		if not is_finite(value) or (str(key).begins_with("resource/") and value < 0.0):
			trial_failure_reason = "corrector_resource_exhaustion"
			Checkpoint.restore(simulation, saved)
			return
		if (str(key).ends_with("total_produced") or str(key).ends_with("total_consumed") or str(key).ends_with("total_lost") or str(key).ends_with("/overflow") or str(key).ends_with("/decay")) and value < float(initial.get(key, 0.0)):
			trial_failure_reason = "negative_integrated_flow"
			Checkpoint.restore(simulation, saved)
			return
	Checkpoint.restore(simulation, saved)
	for id in simulation.state.resources:
		simulation.state.resources[id].amount = float(result["resource/" + str(id)])
	var objects: Array = [simulation.state.resource_statistics, simulation.state.current_run_statistics, simulation.state.simulation_statistics]
	var prefixes: Array[String] = ["lifetime", "run", "offline"]
	for index in range(objects.size()):
		var stats: ResourceStatistics = objects[index]
		if stats == null:
			continue
		var prefix: String = prefixes[index]
		stats.total_overflow = float(result[prefix + "/overflow"])
		stats.total_matter_decayed = float(result[prefix + "/decay"])
		for id in simulation.state.resources:
			var path: String = prefix + "/" + str(id) + "/"
			for field in ["total_produced", "total_consumed", "total_lost"]:
				if result.has(path + field):
					stats._ensure_resource(id)
					stats.statistics[id][field] = result[path + field]
			var peak_key: String = path + "highest_amount"
			if not first.has(peak_key):
				continue
			var peak: float = maxf(float(initial.get(peak_key, 0.0)), float(first[peak_key]))
			# Preserve reference microstep peaks, rather than recording the
			# fictitious lump production of a long Simulation.update(delta).
			if float(endpoint.get(peak_key, 0.0)) > float(initial.get(peak_key, 0.0)):
				var resource_key: String = "resource/" + str(id)
				var last_increment: float = float(endpoint[resource_key]) - float(before_probe[resource_key])
				peak = maxf(peak, float(endpoint[peak_key]) + float(result[resource_key]) - float(predicted[id]) - last_increment)
			stats._ensure_resource(id)
			stats.statistics[id]["highest_amount"] = peak
	simulation.state.total_overflow_this_prestige = float(result["reward/overflow"])
	simulation.state.total_matter_decayed_this_prestige = float(result["reward/decay"])

	simulation.state.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(end))

archived_sources.benchmark_before_final_fingerprints:
extends SceneTree

const Adaptive = preload("res://tests/experimental/adaptive_offline.gd")
const Feedback = preload("res://tests/experimental/feedback_offline.gd")
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")

class Log extends RefCounted:
	var events: Array[Dictionary] = []
	func record_event(category: String, event: String, details: Dictionary = {}, source: String = "game") -> void:
		events.append({"category": category, "event": event, "details": details.duplicate(true), "source": source})

func _initialize() -> void:
	call_deferred("_run")

func _run() -> void:
	var options: Dictionary = {"scenario": "fresh", "duration": "60", "tolerance": "0.0001", "maximum": "60", "absolute": "1e-8", "audit": "60", "mode": "compare", "repeats": "1", "distributed": "true"}
	for argument in OS.get_cmdline_user_args():
		var pair: PackedStringArray = argument.trim_prefix("--").split("=", true, 1)
		if pair.size() == 2:
			options[pair[0]] = pair[1]
	for repeat_index in range(int(options["repeats"])):
		var result: Dictionary = await measure(options)
		result["repeat"] = repeat_index
		print("ADAPTIVE_JSON " + JSON.stringify(result))
	quit()

static func make_state(scenario: String) -> GameState:
	var state := GameState.new()
	state.gameplay_rng.seed = 123456
	state.gameplay_log = Log.new()
	if scenario.begins_with("feedback_"):
		return make_feedback_state(scenario)
	if scenario == "fresh":
		return state
	if scenario in ["automation", "upgrade_automation", "starved", "cycles", "coupled"]:
		state.set_resource_amount(ResourceIds.HEAT, 200000.0)
		state.set_resource_amount(ResourceIds.MATTER, 2000.0)
		state.set_resource_amount(ResourceIds.ASH, 500.0)
		for g in state.generators.values():
			g.unlocked = true
			if not g.definition.cycle_based:
				g.level = 3
		if scenario in ["automation", "upgrade_automation"]:
			for id in GeneratorAutomationManager.AUTOMATABLE_GENERATOR_IDS:
				var manager = state.generator_automation_manager if scenario == "automation" else state.upgrade_automation_manager
				state.eternal_flame_state.unlock_technology(manager.get_automation_technology_id(id))
				manager.set_enabled(id, true)
		if scenario == "starved":
			for id in state.resources:
				state.set_resource_amount(id, 0.0)
			for g in state.generators.values():
				if g.get_active_inputs().is_empty():
					g.manually_paused = true
		if scenario == "cycles":
			for g in state.generators.values():
				g.manually_paused = not g.definition.cycle_based
			var simulation := Simulation.new(state)
			state.get_upgrade("infernal_forge_unlock").level = 1
			state.get_upgrade("infernal_forge_critical_chance").level = 1
			state.get_upgrade("infernal_forge_recrystallization").level = 1
			simulation.rebuild_upgrade_effects()
			state.realm_effects.matter_decay_threshold = 1e15
			state.realm_effects.heat_leak_threshold = 1e15
			state.set_resource_amount(ResourceIds.MATTER, 1e12)
			state.set_resource_amount(ResourceIds.HEAT, 1e12)
			for id in ["infernal_forge", "relic_shard_extractor"]:
				var g: Generator = state.get_generator(id)
				g.definition.base_cost = 0.0
				g.auto_run_cycles = true
				state.eternal_flame_state.unlock_technology(EternalFlameState.get_cycle_auto_run_technology_id(id))
			var forge: Generator = state.get_generator("infernal_forge")
			forge.operation_mode_id = "fast"
			forge.modifiers.clear()
			forge.invalidate_production_modifier_cache()
			for effect in forge.event_effects:
				effect.event_chance = 0.5
			state.get_generator("relic_shard_extractor").operation_mode_id = "forge_relic"
			state.relic_manager.add_stackable_item("relic_shard", 1000)
			var entry: Dictionary = state.relic_manager.get_inventory_entry_at_slot(0)
			state.relic_manager.move_inventory_entry_to_machine_slot(str(entry["instance_id"]), "relic_shard_extractor", 0)
		return state
	var producer: Generator = state.get_generator("atomic_friction")
	if scenario == "stable":
		# Existing realm formula raises the threshold; no leak-free formula fork.
		state.realm_configuration.stability = 1e20
		state.rebuild_realm_effects()
	elif scenario == "heat":
		state.set_resource_amount(ResourceIds.HEAT, state.realm_effects.heat_leak_threshold + 1.0)
	elif scenario == "matter":
		state.set_resource_amount(ResourceIds.MATTER, state.realm_effects.matter_decay_threshold * 2.0)
		state.set_resource_amount(ResourceIds.HEAT, state.realm_effects.heat_leak_threshold * 1.2)
	elif scenario == "ash":
		state.set_resource_amount(ResourceIds.ASH, 10000.0)
	elif scenario == "essence":
		producer.operation_mode_id = "intensified_friction"
		producer.get_operation_mode().unlocked = true
		producer.level = 1000
		state.set_resource_amount(ResourceIds.ESSENCE, 10000.0)
	elif scenario == "idle":
		for g in state.generators.values():
			g.manually_paused = true
	return state

func measure(options: Dictionary) -> Dictionary:
	var scenario: String = options["scenario"]
	var duration: float = float(options["duration"])
	var adaptive_state: GameState = make_state(scenario)
	var prototype = Feedback.new(Simulation.new(adaptive_state)) if options.get("integrator", "original") == "map" else Adaptive.new(Simulation.new(adaptive_state))
	prototype.numerical_retry_max_ticks = int(options.get("retry_max", str(prototype.numerical_retry_max_ticks)))
	prototype.trace_attempts = options.get("trace", "false") == "true"
	prototype.maximum_step = float(options["maximum"])
	prototype.minimum_step = float(options.get("minimum", "0.1"))
	prototype.event_safety_margin = float(options.get("margin", "0.1"))
	prototype.fallback_window_ticks = int(options.get("fallback_window", "10"))
	prototype.force_exact = options.get("force_exact", "false") == "true"
	prototype.allow_environmental_feedback = options.get("environment", "true") == "true"
	prototype.relative_tolerance = float(options["tolerance"])
	prototype.absolute_tolerance = float(options["absolute"])
	prototype.audit_interval = float(options["audit"])
	prototype.distribute_error_budget = options["distributed"] == "true"
	var memory_before: int = OS.get_static_memory_usage()
	var start: int = Time.get_ticks_usec()
	var counters: Dictionary = prototype.run(duration)
	var adaptive_seconds: float = float(Time.get_ticks_usec() - start) / 1e6
	var memory_after: int = OS.get_static_memory_usage()
	var reference: GameState = make_state(scenario)
	var simulation := Simulation.new(reference)
	var manager := TimeManager.new(simulation)
	reference.simulation_statistics = manager.simulation_statistics
	var elapsed: float = 0.0
	var max_error: Dictionary = {"resource_abs": 0.0, "resource_rel": 0.0, "statistics_abs": 0.0, "statistics_rel": 0.0, "normalized": 0.0, "worst_key": ""}
	var strict: bool = counters["strict_failure"] == ""
	var rng: bool = true
	var audits: int = 0
	var field_deviations: Dictionary = {}
	var reference_audit_usec: int = 0
	start = Time.get_ticks_usec()
	var evaluations: int = 0
	for tick in range(ceili(duration / TimeManager.OFFLINE_MAX_GAME_STEP)):
		var delta: float = minf(TimeManager.OFFLINE_MAX_GAME_STEP, duration - elapsed)
		if delta <= 0.0:
			break
		elapsed = minf(duration, elapsed + delta)
		manager.game_time += delta
		manager.offline_time += delta
		manager.prestige_time += delta
		manager.current_offline_duration += delta
		reference.set_lava_mite_dormancy_penalty(manager.get_dormancy_penalty(elapsed))
		simulation.update(delta, true)
		evaluations += 1
		if prototype.samples.has(tick + 1):
			var audit_start: int = Time.get_ticks_usec()
			var sample: Dictionary = prototype.samples[tick + 1]
			var reference_values: Dictionary = Metrics.numeric(reference, manager)
			var errors: Dictionary = Metrics.compare(reference_values, sample["numeric"], prototype.absolute_tolerance, prototype.relative_tolerance)
			for field in reference_values:
				var value: float = float(reference_values[field])
				var difference: float = absf(value - float(sample["numeric"].get(field, 0.0)))
				if not field_deviations.has(field):
					field_deviations[field] = {"absolute": 0.0, "relative": 0.0}
				field_deviations[field]["absolute"] = maxf(float(field_deviations[field]["absolute"]), difference)
				field_deviations[field]["relative"] = maxf(float(field_deviations[field]["relative"]), difference / maxf(absf(value), prototype.absolute_tolerance))
			for key in max_error:
				if key == "worst_key":
					continue
				if float(errors[key]) > float(max_error[key]):
					max_error[key] = errors[key]
			max_error["worst_key"] = errors["worst_key"] if float(errors["normalized"]) >= float(max_error["normalized"]) else max_error["worst_key"]
			strict = strict and Metrics.discrete(reference) == sample["discrete"]
			rng = rng and str(reference.gameplay_rng.state) == sample["rng"]
			audits += 1
			reference_audit_usec += Time.get_ticks_usec() - audit_start
	var reference_wall: float = float(Time.get_ticks_usec() - start) / 1e6
	var reference_seconds: float = reference_wall - float(reference_audit_usec) / 1e6
	var final_error: Dictionary = Metrics.compare(Metrics.numeric(reference, manager), Metrics.numeric(adaptive_state, prototype.manager), prototype.absolute_tolerance, prototype.relative_tolerance)
	strict = strict and Metrics.discrete(reference) == Metrics.discrete(adaptive_state)
	rng = rng and reference.gameplay_rng.state == adaptive_state.gameplay_rng.state
	var result: Dictionary = {"scenario": scenario, "duration": duration, "integrator": options.get("integrator", "original"), "attempts": prototype.attempts, "relative_tolerance": prototype.relative_tolerance,
		"absolute_tolerance": prototype.absolute_tolerance, "maximum_step": prototype.maximum_step,
		"retry_max_ticks": prototype.numerical_retry_max_ticks, "fallback_window_ticks": prototype.fallback_window_ticks, "event_safety_margin": prototype.event_safety_margin, "minimum_step": prototype.minimum_step,
		"distributed_budget": prototype.distribute_error_budget, "audit_interval": prototype.audit_interval,
		"reference_seconds": reference_seconds, "reference_wall_with_audits": reference_wall, "reference_audit_usec": reference_audit_usec, "adaptive_seconds": adaptive_seconds, "speedup": reference_seconds / maxf(adaptive_seconds, 1e-9),
		"reference_evaluations": evaluations, "adaptive_counters": counters, "maximum_sampled_deviation": max_error,
		"final_deviation": final_error, "field_deviations": field_deviations, "final_reference": Metrics.numeric(reference, manager), "final_candidate": Metrics.numeric(adaptive_state, prototype.manager), "audits": audits, "discrete_parity": strict, "rng_parity": rng,
		"accuracy_pass": float(max_error["normalized"]) <= 1.0 and float(final_error["normalized"]) <= 1.0,
		"static_memory_before": memory_before, "static_memory_after": memory_after, "engine_static_peak": OS.get_static_memory_peak_usage(),
		"trace_bytes": var_to_bytes(prototype.samples).size(),
		"sources": {"simulation": String(simulation.get_script().source_code).sha256_text(),
			"time_manager": String(manager.get_script().source_code).sha256_text(),
			"game_state": String(reference.get_script().source_code).sha256_text(),
			"rng": FileAccess.get_file_as_string("res://Game/gameplay_random.gd").sha256_text(),
			"prototype": FileAccess.get_file_as_string("res://tests/experimental/adaptive_offline.gd").sha256_text(),
			"checkpoint": FileAccess.get_file_as_string("res://tests/experimental/continuous_checkpoint.gd").sha256_text(),
			"metrics": FileAccess.get_file_as_string("res://tests/experimental/adaptive_metrics.gd").sha256_text(),
			"feedback": FileAccess.get_file_as_string("res://tests/experimental/feedback_offline.gd").sha256_text(),
			"fixture": FileAccess.get_file_as_string("res://tests/experimental/adaptive_benchmark.gd").sha256_text()}, "engine": Engine.get_version_info()["string"]}
	if options["mode"] == "manager":
		var managed: GameState = make_state(scenario)
		var managed_time := TimeManager.new(Simulation.new(managed))
		start = Time.get_ticks_usec()
		await managed_time.simulate_offline(duration)
		result["manager_seconds"] = float(Time.get_ticks_usec() - start) / 1e6
		result["manager_yields"] = managed_time.offline_yield_count
		result["manager_steps"] = managed_time.offline_steps_processed
		result["manager_vs_direct"] = Metrics.compare(Metrics.numeric(reference, manager), Metrics.numeric(managed, managed_time), prototype.absolute_tolerance, prototype.relative_tolerance)
		result["manager_discrete_parity"] = Metrics.discrete(reference) == Metrics.discrete(managed)
		result["manager_rng_parity"] = reference.gameplay_rng.state == managed.gameplay_rng.state
	return result

# Input-free Matter production is a synthetic data-driven integration control.
# Actual existing Matter-producing consumers stay on exact fallback.
static func make_feedback_state(scenario: String) -> GameState:
	if scenario in ["feedback_starved", "feedback_recovery"]:
		var starved: GameState = make_state("starved")
		if scenario == "feedback_recovery":
			starved.get_generator("atomic_friction").manually_paused = false
		return starved
	var state: GameState = make_state("heat")
	var producer: Generator = state.get_generator("atomic_friction")
	if scenario in ["feedback_held", "feedback_combined", "feedback_high", "feedback_dynamic", "feedback_representative", "feedback_stored"]:
		state.set_resource_amount(ResourceIds.MATTER, state.realm_effects.matter_decay_threshold * 2.0)
	if scenario in ["feedback_matter", "feedback_combined", "feedback_threshold", "feedback_representative"]:
		var mode := GeneratorOperationMode.new("source", "Test source", "Synthetic input-free Matter fixture", 1.0, 1.0, 1.0, 0.0, [], [GeneratorIO.new(ResourceIds.MATTER, 0.25)])
		var definition := GeneratorDefinition.new("feedback_source", "Test source", 1.0, 1.0, ResourceIds.HEAT, false, "", [mode])
		var source := Generator.new(definition)
		source.unlocked = true
		source.level = 1
		state.generators[definition.id] = source
		state.set_resource_amount(ResourceIds.MATTER, state.realm_effects.matter_decay_threshold + 1.0)
	if scenario == "feedback_matter":
		producer.manually_paused = true
	if scenario == "feedback_threshold":
		state.set_resource_amount(ResourceIds.MATTER, state.realm_effects.matter_decay_threshold - 0.01)
		state.set_resource_amount(ResourceIds.HEAT, state.realm_effects.heat_leak_threshold - 0.01)
	if scenario == "feedback_equilibrium":
		# Find the map's actual equilibrium by reference ticks, not an ODE root.
		var simulation := Simulation.new(state)
		for _tick in range(10000):
			simulation.update(0.1, true)
	if scenario == "feedback_high":
		state.set_resource_amount(ResourceIds.HEAT, state.realm_effects.heat_leak_threshold * 100.0)
		state.set_resource_amount(ResourceIds.MATTER, state.realm_effects.matter_decay_threshold * 10.0)
	if scenario == "feedback_dynamic":
		var modifier := Modifier.new(ModifierTypes.PRODUCTION, ResourceIds.HEAT, 0.05)
		modifier.dynamic = true
		modifier.dynamic_resource_id = ResourceIds.HEAT
		modifier.dynamic_formula = Modifier.DYNAMIC_RESOURCE_SQRT_INVERSE
		modifier.id = "feedback_test_heat_sensitivity"
		producer.modifiers.append(modifier)
		producer.invalidate_production_modifier_cache()
	if scenario in ["feedback_representative", "feedback_stored"]:
		producer.level = 10
		state.set_resource_amount(ResourceIds.HEAT, state.realm_effects.heat_leak_threshold * 3.0)
		state.set_resource_amount(ResourceIds.MATTER, state.realm_effects.matter_decay_threshold * 2.0)
	return state

