extends SceneTree
const Fixture = preload("res://tests/experimental/adaptive_benchmark.gd")
const Metrics = preload("res://tests/experimental/adaptive_metrics.gd")
class Traced extends "res://tests/experimental/feedback_offline.gd":
	var last_report: int = 0
	func _advance(delta: float, end: float) -> void:
		super(delta, end)
		if Time.get_ticks_usec() - last_report >= 5000000:
			last_report = Time.get_ticks_usec()
			print("FEEDBACK_PROGRESS " + JSON.stringify({"elapsed": elapsed, "evaluations": counters["evaluations"], "accepted": counters["accepted"], "rejected": counters["rejected"], "fallback_ticks": counters["fallback_ticks"], "fields": counters["rejection_fields"], "reasons": counters["rejection_reasons"]}))
func _initialize() -> void:
	call_deferred("_run")
func _run() -> void:
	var state: GameState = Fixture.make_state("feedback_stored")
	var prototype = Traced.new(Simulation.new(state))
	var start: int = Time.get_ticks_usec()
	var counters: Dictionary = prototype.run(86400.0)
	print("FEEDBACK_DIAGNOSTIC " + JSON.stringify({"seconds": float(Time.get_ticks_usec() - start) / 1e6, "counters": counters, "numeric": Metrics.numeric(state, prototype.manager), "discrete": Metrics.discrete(state), "rng": str(state.gameplay_rng.state)}))
	quit()
